    const pad = Math.ceil((ow + 1) * s) + 1, w = Math.ceil((textWidth(str, size) + size * 0.12) * s) + 2 * pad + bw, top = Math.ceil(size * 0.35 * s), h = Math.ceil(size * 1.4 * s) + 2 * pad + Math.ceil(sh * s) + top;   // top = headroom for stacked Vietnamese marks
